        "explicacion": "$P_{CC,max} = \\frac{2}{\\pi} \\frac{V_{CC}^2}{R_L} = \\frac{2}{\\pi} \\frac{225}{8\\,\\Omega} \\approx 17.90\\text{ W}$. Rendimiento: $\\eta = \\frac{14.06}{17.90} \\approx 78.5\\%$.",
        "tipoRespuesta": "numerica",
        "unidad": "W",
        "solucion": 17.9,
        "valorEsperado": 17.9,
        "tolerancia": 0.05,
        "simbolo": "P_{CC,max}",
        "explicacionPaso": "$P_{CC,max} = \\frac{2}{\\pi} \\times \\frac{225}{8} = 17.90\\text{ W}$."
